/**
 * FS AI — Internal AI-draft banner protection.
 *
 * An AI-generated draft carries an internal warning block at the top of its
 * body (generated by backend/agents/autonomy/content.js):
 *
 *   AI-DRAFT — needs fact-check + owner approval.
 *
 *   This draft was written by workers-ai (@cf/openai/gpt-oss-120b). It has
 *   NOT been fact-checked and must pass fact-checking and owner approval
 *   before it can be published.
 *
 * That block is internal scaffolding: the fact-checker already ignores it
 * (backend/agents/autonomy/factcheck.js BANNER_LINE_RE), but until
 * 2026-11-20 nothing removed it at publication time — the publish path
 * only flipped status, and the public article page renders the body
 * verbatim. A published AI draft would therefore have shown the warning
 * (including its then-false "has NOT been fact-checked" line) to readers.
 *
 * This module is the single definition of what counts as a banner line,
 * shared by the publish layer and the public renderer:
 *
 *   - stripDraftBanner(body): remove the complete LEADING banner block
 *     (banner lines + surrounding blank lines) and nothing else.
 *   - hasDraftBanner(body): fail-closed detector — any banner-like line
 *     ANYWHERE in the body.
 *   - stripAllDraftBannerLines(body): renderer strip — drop banner lines
 *     wherever they appear, so a body that somehow still carries one can
 *     never render publicly.
 *
 * A line counts as a banner line ONLY when it STARTS with one of the
 * markers (after optional whitespace). Prose that merely mentions
 * "AI-DRAFT" in the middle of a sentence is legitimate content and is
 * never touched. Pure functions, no I/O, no LLM.
 */
export const DRAFT_BANNER_LINE_RE =
  /^\s*(AI-DRAFT\b.*|This draft was written by\b.*|It has NOT been fact-checked\b.*|SCAFFOLD\b.*)$/i;

/** True when one line is an internal banner/scaffold line. */
export function isDraftBannerLine(line) {
  return DRAFT_BANNER_LINE_RE.test(String(line ?? ''));
}

/**
 * Remove the complete LEADING internal banner block: the AI-DRAFT line,
 * the "This draft was written by…" line (whether on one line or split
 * across two), and the blank lines around them. Stops at the first line
 * that is neither blank nor a banner line.
 *
 * Returns the input UNCHANGED (same string) when the leading block holds
 * no banner line — a banner-free body, and a body that merely mentions
 * AI-DRAFT mid-text, both come back byte-identical.
 */
export function stripDraftBanner(body) {
  if (typeof body !== 'string' || body === '') return body;
  const lines = body.split('\n');
  let i = 0;
  let sawBanner = false;
  while (i < lines.length) {
    if (isDraftBannerLine(lines[i])) {
      sawBanner = true;
      i += 1;
      continue;
    }
    if (lines[i].trim() === '') {
      i += 1;
      continue;
    }
    break;
  }
  if (!sawBanner) return body;
  return lines.slice(i).join('\n');
}

/**
 * Fail-closed detector: true when ANY line anywhere in the body is a
 * banner line (leading, middle or trailing). Used by the publish layer
 * after stripping: if anything is left, publication is refused.
 */
export function hasDraftBanner(body) {
  if (typeof body !== 'string' || body === '') return false;
  return body.split('\n').some(isDraftBannerLine);
}

/**
 * Renderer strip: the body as if the banner had never been there. First
 * remove the leading banner block together with its surrounding blank
 * lines (stripDraftBanner), then drop any banner line that still remains
 * further down. Only lines starting with a banner marker are dropped;
 * all other lines — including prose that mentions AI-DRAFT mid-sentence —
 * are kept verbatim.
 */
export function stripAllDraftBannerLines(body) {
  if (typeof body !== 'string' || body === '') return body;
  const stripped = stripDraftBanner(body);
  if (!hasDraftBanner(stripped)) return stripped;
  return stripped
    .split('\n')
    .filter((line) => !isDraftBannerLine(line))
    .join('\n');
}
